-- English-primary names for every source a reader meets: the grammar books, lexicons, tafsīrs and iʿrāb books.
-- title_en is the scholarly citation form «Transliterated title (Author)»; title_translit the title alone;
-- title_gloss_en what the title means; author_en the author as English prose names him; death years AH/CE.
ALTER TABLE ar_ling_source ADD COLUMN title_translit TEXT;
ALTER TABLE ar_ling_source ADD COLUMN title_gloss_en TEXT;
ALTER TABLE ar_ling_source ADD COLUMN author_en TEXT;
